WITH m AS (SELECT s.loan_id, s.snapshot_date, CASE WHEN s.days_past_due=0 THEN 0 WHEN s.days_past_due<30 THEN 1 WHEN s.days_past_due<60 THEN 2 WHEN s.days_past_due<90 THEN 3 ELSE 4 END AS b, s.loan_status, LEAD(CASE WHEN s.days_past_due=0 THEN 0 WHEN s.days_past_due<30 THEN 1 WHEN s.days_past_due<60 THEN 2 WHEN s.days_past_due<90 THEN 3 ELSE 4 END) OVER (PARTITION BY s.loan_id ORDER BY s.snapshot_date) AS bn, LEAD(s.snapshot_date) OVER (PARTITION BY s.loan_id ORDER BY s.snapshot_date) AS dn FROM loan_monthly_snapshot s JOIN loan l USING (loan_id) WHERE l.purpose='Equity Release / Top-up') SELECT b, bn, COUNT(*) FROM m WHERE snapshot_date=DATE '2025-11-30' AND dn=DATE '2025-12-31' AND loan_status<>'Closed' GROUP BY 1,2 ORDER BY 1,2
